private function produceOne(int $versionId,int $planId,string $group,array $definition,string $key,int $sequence,string $variant=''):array|WP_Error{$variant=sanitize_key($variant);$assetKey=sanitize_key((string)($definition['asset_key']??($group.'-'.$sequence)));$format=strtolower(sanitize_key((string)($definition['format']??'txt')));$filename=$this->normalizedFilename((string)($definition['filename']??''),$assetKey,$format);$purpose=sanitize_text_field((string)($definition['purpose']??$group));$spec=$this->production->createSpec(['product_version_id'=>$versionId,'asset_key'=>$assetKey,'asset_type'=>$group==='marketing'?'marketing_asset':'product_asset','purpose'=>$purpose,'format'=>$format,'variant_key'=>$variant,'content_requirements'=>['filename'=>$filename,'group'=>$group],'design_constraints'=>['generated_locally'=>true,'external_publish'=>false]],$key.'-spec-'.$sequence);if(is_wp_error($spec))return$spec;$linked=$this->production->linkAsset($planId,(int)$spec['id'],true,$sequence);if(is_wp_error($linked))return$linked;$specified=$this->production->transition('spec',(int)$spec['id'],'SPECIFIED');if(is_wp_error($specified))return$specified;$file=$this->producer->write($versionId,$filename,$format,$definition['content']??($definition['pages']??''),$variant);if(is_wp_error($file))return$file;$revision=$this->production->addRevision(['asset_spec_id'=>(int)$spec['id'],'revision_label'=>'U3-1.0','storage_reference'=>(string)$file['storage_reference'],'checksum_sha256'=>(string)$file['checksum_sha256'],'mime_type'=>(string)$file['mime_type'],'byte_size'=>(int)$file['byte_size'],'provenance'=>['generator'=>'digiforge_u3','group'=>$group,'repair_variant'=>$variant,'external_publish'=>false]],$key.'-revision-'.$sequence);if(is_wp_error($revision))return$revision;$qa=$this->qa->inspect($file);foreach($qa['checks']as$index=>$check){$record=$this->production->addQa(['target_type'=>'revision','target_id'=>(int)$revision['id'],'check_type'=>(string)$check['name'],'status'=>($