private function assetDefinitions(mixed $raw,bool $marketing):array{$items=is_array($raw)?$raw:[];$out=[];foreach($items as$index=>$item){if(!is_array($item))continue;$format=strtolower(sanitize_key((string)($item['format']??($marketing?'svg':'html'))));if(!in_array($format,['html','txt','json','csv','svg','pdf'],true))$format=$marketing?'svg':'html';$assetKey=sanitize_key((string)($item['asset_key']??(($marketing?'marketing':'product').'-'.($index+1))));$filename=sanitize_file_name((string)($item['filename']??($assetKey.'.'.$format)));$content=$item['content']??($item['pages']??'');if(is_array($content))$content=implode("\n\n",array_map(static fn($value):string=>is_scalar($value)?(string)$value:wp_json_encode($value),$content));$out[]=['asset_key'=>$assetKey,'filename'=>$filename,'format'=>$format,'purpose'=>sanitize_text_field((string)($item['purpose']??($marketing?'Etsy listing marketing asset':'Customer product asset'))),'content'=>(string)$content];}return$out;}
